for page, (title, question, steps) in DATA.items():
    path = ROOT / "data/problems" / f"mechanics_challenge_page_{page:03d}.json"
    problem = json.loads(path.read_text(encoding="utf-8"))
    problem["title"] = title
    problem["question"] = question
    problem["steps"] = [{"stepId": i + 1, "title": t, "content": c, "knowledge": [], "commonMistakes": []} for i, (t, c) in enumerate(steps)]
    problem["animation"]["variant"] = f"kinematics_problem_{page-3:02d}"
    problem["animation"]["params"] = [{"key": "rate", "label": "播放速度", "min": 0.5, "max": 2, "step": 0.1, "value": 1, "unit": "×"}]
    problem["animation"]["description"] = "动画按原题模型绘制；右侧图表显示本题关键函数或几何关系。"
    problem["analysisPresentation"] = {"collapseEachStep": False, "defaultExpanded": True, "hideStepConversation": True}
    problem["presentation"] = {"coreOnly": True}
    if problem.get("images"):
        problem["images"][0]["caption"] = f"原题页面截取：原书第{page-2}页。"
    path.write_text(json.dumps(problem, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

print(f"curated {len(DATA)} kinematics problems")
